+// SignCommit signs the commit using an on-demand object signer. By default,
+// signing remains best-effort: skipped or failed signing leaves the commit
+// unsigned and logs actionable failures. If require_signed_checkpoint_commits is
+// enabled, skipped or failed signing is returned as an error.
+func SignCommit(ctx context.Context, commit *object.Commit) error {
+	required := settings.IsRequireSignedCheckpointCommitsEnabled(ctx)
+	result := signCommit(ctx, commit)
+	if result.signed {
