+		}
+		logging.Warn(ctx, "failed to sign commit", slog.String("error", result.err.Error()))
+		return nil
+	}
+
+	if required {
+		return fmt.Errorf("checkpoint commit signing is required but %s", result.reason)
+	}
+	return nil
+}
+
+// SignCommitBestEffort signs the commit if possible and never blocks commit creation.
+func SignCommitBestEffort(ctx context.Context, commit *object.Commit) {
+	if err := SignCommit(ctx, commit); err != nil {
