+func signCommit(ctx context.Context, commit *object.Commit) commitSigningResult {
+	if !settings.IsSignCheckpointCommitsEnabled(ctx) {
+		return commitSigningResult{reason: "checkpoint commit signing is disabled"}
+	}
+
+	signer, ok := objectSignerLoader(ctx)
+	if !ok {
+		return commitSigningResult{reason: "no compatible signer is available"}
+	}
+
+	if signer == nil {
+		return commitSigningResult{reason: "no compatible signer is available"}
+	}
+
+	encoded := &plumbing.MemoryObject{}
+	if err := commit.EncodeWithoutSignature(encoded); err != nil {
+		return commitSigningResult{err: fmt.Errorf("encode commit for signing: %w", err)}
+	}
+
+	r, err := encoded.Reader()
+	if err != nil {
+		return commitSigningResult{err: fmt.Errorf("read encoded commit: %w", err)}
