+		return commitSigningResult{err: fmt.Errorf("sign commit: %w", err)}
+	}
+	if len(sig) == 0 {
+		return commitSigningResult{err: errors.New("sign commit: signer returned an empty signature")}
+	}
+
+	commit.Signature = string(sig)
