// CreateCommit creates a git commit object with the given tree, parent, message, and author.
// If parentHash is ZeroHash, the commit is created without a parent (orphan commit).
func CreateCommit(ctx context.Context, repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	return createCommit(ctx, repo, treeHash, parentHash, message, authorName, authorEmail, true)
}

// CreateCommitBestEffort creates a git commit object without enforcing
// require_signed_checkpoint_commits. Use this for non-checkpoint metadata refs.
func CreateCommitBestEffort(ctx context.Context, repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	return createCommit(ctx, repo, treeHash, parentHash, message, authorName, authorEmail, false)
}

func createCommit(ctx context.Context, repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string, requireSigning bool) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	if requireSigning {
		if err := SignCommit(ctx, commit); err != nil {
			return plumbing.ZeroHash, err
		}
	} else {
		SignCommitBestEffort(ctx, commit)
	}

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

type commitSigningResult struct {
	signed bool
	reason string
	err    error
}

// SignCommit signs the commit using an on-demand object signer. By default,
// signing remains best-effort: skipped or failed signing leaves the commit
// unsigned and logs actionable failures. If require_signed_checkpoint_commits is
// enabled, skipped or failed signing is returned as an error.
func SignCommit(ctx context.Context, commit *object.Commit) error {
	signEnabled, required := checkpointCommitSigningSettings(ctx)
	result := signCommit(ctx, commit, signEnabled)
	if result.signed {
		return nil
	}

	if result.err != nil {
		if required {
			return fmt.Errorf("checkpoint commit signing is required: %w", result.err)
		}
		logging.Warn(ctx, "failed to sign commit", slog.String("error", result.err.Error()))
		return nil
	}

	if required {
		return fmt.Errorf("checkpoint commit signing is required but %s", result.reason)
	}
	return nil
}

// SignCommitBestEffort signs the commit if possible and never blocks commit creation.
func SignCommitBestEffort(ctx context.Context, commit *object.Commit) {
	signEnabled, _ := checkpointCommitSigningSettings(ctx)
	result := signCommit(ctx, commit, signEnabled)
	if result.err != nil {
		logging.Warn(ctx, "failed to sign commit", slog.String("error", result.err.Error()))
	}
}

func checkpointCommitSigningSettings(ctx context.Context) (signEnabled, required bool) {
	s, err := settings.Load(ctx)
	if err != nil {
		return true, false
	}
	return s.IsSignCheckpointCommitsEnabled(), s.IsRequireSignedCheckpointCommitsEnabled()
}
